_TABLES = {"orders": "orders", "invoices": "invoices"}


def count_rows(conn, kind: str, since: str) -> int:
    table = _TABLES[kind]  # KeyError for anything not allow-listed
    sql = f"SELECT COUNT(*) FROM {table} WHERE created_at >= ?"
    return conn.execute(sql, (since,)).fetchone()[0]
